    it.rels.slice(0, MAXR).forEach((r, i) => { U.uR0.value[i].set(r.ax, r.ay, r.bx, r.by); U.uR1.value[i].set(r.w, r.rA, r.rB, r.ca + 4 * r.cb + (focus && !(focus.has(r.a) && focus.has(r.b)) ? 16 : 0)); });
    U.uNB.value = Math.min(MAXB, it.blobs.length); U.uNR.value = Math.min(MAXR, it.rels.length); U.uMerge.value = merge;
    ['uC0', 'uC1', 'uC2', 'uC3'].forEach((k, i) => U[k].value.set(S.meta.categories[cats[i]] || '#999999'));
