    tube.renderOrder = 3; tube.userData = ud; tube.castShadow = true; G.cross.add(tube);
    for (const [sp, z] of [[c.a, za], [c.b, zb]]) {
      const port = new THREE.Mesh(new THREE.PlaneGeometry(7.5, 7.5), new THREE.MeshBasicMaterial({ map: portTexture(catColor(sp)), transparent: true, depthWrite: false, opacity: dim ? 0.2 : 1 }));
      port.rotation.x = -Math.PI / 2; port.position.copy(V(sp.x, sp.y, z + 0.06)); port.renderOrder = 4; port.userData = ud; G.cross.add(port);
    }
    const el = document.createElement('div'); el.className = 'vlbl' + (dim ? ' dim' : '');
    el.innerHTML = `<b>↕</b>${esc(c.a.name)} – ${esc(c.b.name)}`;
    const lo = new THREE.CSS2DObject(el); lo.position.copy(curve.getPoint(0.5)); lo.visible = vis.labels; G.cross.add(lo);
