  ring(100, 9, rgb(1)); ring(78, 4, 'rgba(14,20,48,0.8)');
  g.beginPath(); g.arc(128, 128, 46, 0, Math.PI * 2); g.fillStyle = rgb(1); g.fill(); ring(46, 5, 'rgba(255,255,255,0.95)');
  g.fillStyle = '#ffffff'; g.font = 'bold 64px Archivo, Arial, sans-serif'; g.textAlign = 'center'; g.textBaseline = 'middle'; g.fillText('↕', 128, 132);
