/* ============ header / legend ============ */
function renderStats() {
  const eb = S.meta.existing_building, cap = eb.footprint_w * eb.footprint_d;
  const sum = list => list.reduce((a, s) => a + (isPh(s) ? 0 : +s.area_m2), 0);
  const cell = (k, list, capacity) => {
    const v = sum(list), ph = list.filter(isPh).length, over = capacity && v > capacity;
    return `<div class="stat${over ? ' over' : ''}"><div class="k">${k}</div><div class="v">${fmt(v)}${capacity ? ' / ' + fmt(capacity) : ''} m² · ${list.length} tér${ph ? ', ' + ph + ' üres' : ''}</div>` +
      (capacity ? `<div class="meter${over ? ' over' : ''}"><i style="width:${Math.min(100, v / capacity * 100)}%"></i></div>` : '') + `</div>`;
  };
  const ins = S.spaces.filter(s => s.enclosure === 'belso');
  $root.getElementById('stats').innerHTML =
    cell('Földszint (belső)', ins.filter(s => s.level === 'fsz'), cap) + cell('Első emelet', ins.filter(s => s.level === 'em'), cap) +
    cell('Beltér összesen', ins, eb.area_total_m2) + cell('Átmeneti', S.spaces.filter(s => s.enclosure === 'atmeneti')) + cell('Külső', S.spaces.filter(s => s.enclosure === 'kulso'));
}
function renderLegend() {
  const c = S.meta.categories;
  const bar = w => `<svg width="46" height="14" viewBox="0 0 46 14" aria-hidden="true"><path d="M0 ${7 - w * 1.9} Q23 ${7 - w * 0.8} 46 ${7 - w * 1.9} L46 ${7 + w * 1.9} Q23 ${7 + w * 0.8} 0 ${7 + w * 1.9}Z" fill="var(--muted)" opacity=".55"/></svg>`;
  $root.getElementById('legend').innerHTML =
    Object.keys(c).map(k => `<div class="lr"><span class="dot" style="background:${c[k]}"></span>${esc(k)}</div>`).join('') +
    `<div class="lr"><span class="dot" style="background:var(--muted);opacity:.45"></span>áttetsző / halvány mag = terület nincs megadva</div>` +
    `<div class="lr"><span class="sq" style="background:linear-gradient(90deg,${c['Publikus terek']},${c['Privát terek']})"></span>Mező: színátmenet = kapcsolat, összeolvadt terek közös határral</div><div class="sep"></div>` +
    `<div class="lr"><span class="sq" style="background:var(--zone-in);border:1.5px solid var(--wall)"></span>Belső tér (épülethatár)</div>` +
    `<div class="lr"><span class="sq" style="background:var(--zone-semi);border:1.5px dashed var(--wall)"></span>Átmeneti, fedett-nyitott sáv</div>` +
    `<div class="lr"><span class="sq" style="border:1px solid var(--line)"></span>Külső tér</div>` +
    `<div class="lr"><span class="sq" style="background:var(--vol);opacity:.55;border:1.5px solid var(--vol-edge)"></span>Jelenlegi O épület (27×27 m, 2 szint)</div>` +
    `<div class="lr"><span class="dot" style="width:14px;height:14px;background:var(--ink);color:var(--panel);display:grid;place-items:center;font:700 10px var(--f-body)">↕</span>Szintközi kapcsolat (portál + függőleges híd)</div><div class="sep"></div>` +
    [3, 2, 1].map(w => `<div class="lr">${bar(w)}${WLABEL[w]}</div>`).join('') +
    `<div class="lr"><svg width="46" height="12" viewBox="0 0 46 12" aria-hidden="true"><line x1="0" y1="6" x2="46" y2="6" stroke="var(--avoid)" stroke-width="1.6" stroke-dasharray="5 4"/></svg>kerülendő szomszédság</div>`;
}

/* ============ panel ============ */
const paneTer = $root.getElementById('pane-ter');
const zoneLabel = sp => sp.enclosure === 'belso' ? S.meta.levels[sp.level].label : S.meta.enclosures[sp.enclosure].label;
function renderPanel() {   // tells embedding pages what the panel shows now
  renderPanelBody();
  window.dispatchEvent(new CustomEvent('oblob:panel', { detail: { selected: selRel === null && selected && byId(selected) ? selected : null } }));
}
function renderPanelBody() {
  if (selRel !== null && S.relations[selRel]) return renderRelation(selRel);
  if (selected && byId(selected)) return renderSpace(byId(selected));
  paneTer.innerHTML = `<div class="actions"><button class="btn primary" id="newSpace">+ Új tér hozzáadása</button></div>
    <p class="hint">Kattints egy blobra vagy egy sorra a szerkesztéshez, egy hídra a kapcsolat adataihoz. A blobok egérrel húzhatók a saját szintjükön. A „Kibogozás” úgy rendezi a tereket, hogy a hidak ne fussanak át más tereken.</p>` +
    Object.keys(S.meta.categories).map(cat => {
      const sps = S.spaces.filter(s => s.category === cat); if (!sps.length) return '';
      return `<div class="group"><h3>${esc(cat)}</h3>` + sps.map(sp => `<div class="row" tabindex="0" data-id="${sp.id}"><span class="dot${isPh(sp) ? ' ph' : ''}" style="background:${catColor(sp)}"></span><span class="nm"><span class="zchip ${sp.enclosure}">${ZCHIP[zkey(sp)]}</span>${esc(sp.name)}${isAdded(sp) ? '<span class="newtag">ÚJ</span>' : ''}</span><span class="mt">${isPh(sp) ? '– m²' : fmt(+sp.area_m2) + ' m²'}</span></div>`).join('') + `</div>`;
    }).join('') + (removedList().length ? `<div class="group removed"><h3>Kivett terek (${removedList().length})</h3>` +
      removedList().map((x, i) => `<div class="row"><span class="dot" style="background:${S.meta.categories[x.space.category] || '#999'};opacity:.4"></span><span class="nm">${esc(x.space.name)}</span><button class="btn" data-restore="${i}">Visszaállítás</button></div>`).join('') + `</div>` : '');
  paneTer.querySelectorAll('.row[data-id]').forEach(r => { r.onclick = () => select(r.dataset.id); r.onkeydown = e => { if (e.key === 'Enter') select(r.dataset.id); }; });
  paneTer.querySelectorAll('[data-restore]').forEach(b => b.onclick = () => restoreSpace(+b.dataset.restore));
  paneTer.querySelector('#newSpace').onclick = addSpace;
}
const isAdded = sp => sp.origin === 'kiegeszites';
const removedList = () => (Array.isArray(S.removed) ? S.removed : []);

/* ============ adding / removing spaces ============ */
function placeFree(sp) {     // nearest free spot for sp in its own zone, spiralling out from the building centre
  const others = S.spaces.filter(s => s !== sp), sz = {};
  S.spaces.forEach(s => sz[s.id] = blobSize(s));
  const r = sz[sp.id].rh, Z = zoneRects(others, sz), cx = (Z.inR[0] + Z.inR[2]) / 2, cy = (Z.inR[1] + Z.inR[3]) / 2;
  const outside = (x, y, R, g) => x < R[0] - r - g || x > R[2] + r + g || y < R[1] - r - g || y > R[3] + r + g;
  const gap = (x, y, R) => Math.hypot(Math.max(R[0] - x, 0, x - R[2]), Math.max(R[1] - y, 0, y - R[3])) - r;
  const ok = (x, y) => {
    for (const o of others) if (grp(o) === grp(sp) && Math.hypot(o.x - x, o.y - y) < r + sz[o.id].rh + 2) return false;
    if (sp.enclosure === 'atmeneti') return outside(x, y, Z.inR, 0.6) && gap(x, y, Z.inR) < 6;
    if (sp.enclosure === 'kulso') return outside(x, y, Z.se, 2.5);
    return true;
  };
  for (let rad = 0; rad < 200; rad += 1.5) {
    const n = Math.max(1, Math.round(rad * 0.8));
    for (let k = 0; k < n; k++) {
      const a = (k / n) * Math.PI * 2 + rad, x = cx + rad * Math.cos(a), y = cy + rad * Math.sin(a);
      if (ok(x, y)) { sp.x = +x.toFixed(2); sp.y = +y.toFixed(2); return; }
    }
  }
}
function addSpace() {
  const sp = { id: 'ter_' + Date.now().toString(36), row: '', name: 'Új tér', category: 'Fél-publikus terek', user_group: '', alt_functions: '',
    capacity: '', m2_per_person: '', area_m2: null, area_detail: '', noise: '', smell: '', time_window: '', location: '', links: '', count: '',
    note: '', cell_comments: '', level: 'fsz', enclosure: 'belso', anchor: '', origin: 'kiegeszites', x: 0, y: 0 };
  S.spaces.push(sp); placeFree(sp);
  buildBlobs(2); renderStats(); renderTable(); renderRelPane(); save(); select(sp.id);
  const n = $root.getElementById('f_name'); if (n) { n.focus(); n.select(); }
}
function deleteSpace(id) {   // spaces from the original program go to "Kivett terek" and can be restored; added ones are dropped
  const sp = byId(id); if (!sp) return;
  if (!isAdded(sp)) {
    if (!Array.isArray(S.removed)) S.removed = [];
    S.removed.push({ space: clone(sp), relations: clone(S.relations.filter(r => r.a === id || r.b === id)) });
  }
  S.spaces = S.spaces.filter(s => s.id !== id);
  S.relations = S.relations.filter(r => r.a !== id && r.b !== id);
  selected = null; selRel = null;
  buildBlobs(2); renderStats(); renderTable(); renderRelPane(); save(); renderPanel();
}
function restoreSpace(i) {
  const x = removedList()[i]; if (!x) return;
  S.removed.splice(i, 1);
  const sp = clone(x.space); S.spaces.push(sp);
  const sz = {}; S.spaces.forEach(s => sz[s.id] = blobSize(s));
  if (S.spaces.some(o => o !== sp && grp(o) === grp(sp) && Math.hypot(o.x - sp.x, o.y - sp.y) < sz[o.id].rh + sz[sp.id].rh)) placeFree(sp);
  for (const r of x.relations) if (byId(r.a) && byId(r.b) && !S.relations.some(q => relKey(q.a, q.b) === relKey(r.a, r.b))) S.relations.push(r);
  buildBlobs(2); renderStats(); renderTable(); renderRelPane(); save(); select(sp.id);
}

/* ============ relations tab: define a relation between any two spaces ============ */
