      if (isAdded(sp)) { nameCell.fill = fill('FFD9EFE6'); nameCell.value = sp.name + ' (új)'; }
      const noteTxt = [isAdded(sp) ? 'Kiegészítés – nem szerepelt az eredeti programtervben.' : '', sp.cell_comments || ''].filter(Boolean).join('\n');
      if (noteTxt) nameCell.note = noteTxt;
