      Object.assign(ws.getCell(r, 7), { value: refs.length ? { formula: `SUM(${refs.join(',')})`, result: val } : 0, font: { bold: true }, numFmt: '#,##0.0#', border: box, fill: fill('FFF3F5F3') });
