function resize() {
  const w = host.clientWidth, h = host.clientHeight; if (!w || !h) return;
  renderer.setSize(w, h, false); renderer.domElement.style.width = w + 'px'; renderer.domElement.style.height = h + 'px';
  labelR.setSize(w, h); camera.aspect = w / h; camera.updateProjectionMatrix();
}
new ResizeObserver(resize).observe(host);
function tick() {
  if (relaxing > 0) {
    const heat = 0.25 + 0.75 * relaxing / relaxTotal;
    for (let i = 0; i < 4; i++) relaxStep(S.spaces, S.relations, heat);
    relaxing--; buildBlobs(relaxing ? 1 : 2);
    if (relaxing === 0) { save(); renderTable(); }
  }
  if (host.clientWidth) { controls.update(); renderer.render(scene, camera); labelR.render(scene, camera); }
  requestAnimationFrame(tick);
}
const mq = window.matchMedia('(prefers-color-scheme: dark)');
