// ===== Hub layout for the blob diagram (appended by tools/import_blob.ps1 after the page's own script) =====
// Runs inside initBlobDiagram with $root (shadow root) and $host. Moves existing controls (their handlers stay)
// into two menus, and frames the building instead of the whole plot, where the 8600 m² park dwarfs everything.
(() => {
  const $ = (id) => $root.getElementById(id);
  const bar = $root.querySelector('.ui.tl');
  const menu = (label, count) => {
    const d = document.createElement('details'); d.className = 'pop';
    d.innerHTML = `<summary>${label}${count ? ` <span class="n">${count}</span>` : ''}</summary><div class="menu"></div>`;
    return d;
  };

  const layers = [...bar.querySelectorAll('[data-layer]')];
  const layerMenu = menu('Rétegek', layers.length);
  layerMenu.querySelector('.menu').append(...layers);

  const settings = menu('Beállítások');
  settings.querySelector('.menu').append($('explode').closest('.ctl'), $('merge').closest('.ctl'), $('phArea').closest('.ctl'));

  // views: "3D" and "Felülnézet" frame the building and its forecourt; "Teljes telek" fits every space, as before
  const views = document.createElement('span'); views.className = 'views';
  const whole = document.createElement('button'); whole.className = 'btn'; whole.type = 'button'; whole.textContent = 'Teljes telek';
  views.append($('v3d'), $('vtop'), whole);

  const seg = bar.querySelector('.seg'), spacer = bar.querySelector('.spacer');
  bar.replaceChildren(layerMenu, settings, spacer, views, seg);

  // one menu open at a time; a click elsewhere or Escape closes it
  const pops = [layerMenu, settings];
  pops.forEach((p) => p.addEventListener('toggle', () => { if (p.open) pops.forEach((q) => { if (q !== p) q.open = false; }); }));
  $root.addEventListener('pointerdown', (e) => { if (!e.composedPath().some((n) => pops.includes(n))) pops.forEach((p) => { p.open = false; }); });
  $root.addEventListener('keydown', (e) => { if (e.key === 'Escape') pops.forEach((p) => { p.open = false; }); });

  const api = window.__oblob;
  function frameCore(top) {
    const S = api.S(), ph = +S.meta.placeholder_area_m2 || 40;
    const core = S.spaces.filter((s) => s.enclosure !== 'kulso');
    if (!core.length) { api.frame(top); return; }
    let x0 = 1e9, y0 = 1e9, x1 = -1e9, y1 = -1e9;
    for (const s of core) {
      const a = +s.area_m2 > 0 ? +s.area_m2 : ph, r = Math.sqrt(a / Math.PI);
      x0 = Math.min(x0, s.x - r); y0 = Math.min(y0, s.y - r); x1 = Math.max(x1, s.x + r); y1 = Math.max(y1, s.y + r);
    }
    const cx = (x0 + x1) / 2, cy = (y0 + y1) / 2, span = Math.max(x1 - x0, y1 - y0, 30) * 1.8;
    if (top) api.look(cx, cy, 2, cx, cy - 0.01, span * 1.45);
    else api.look(cx, cy, 2, cx - span * 0.45, cy - span * 0.78, span * 0.62);
  }
  $('v3d').onclick = () => frameCore(false);
  $('vtop').onclick = () => frameCore(true);
  whole.onclick = () => api.frame(false);

  // programme sheets (js/program-sheets.js, under the diagram): the selected space's sheet text in the side panel
  window.addEventListener('oblob:panel', (e) => {
    const sheets = window.PROGRAM_SHEETS, id = e.detail && e.detail.selected, hit = id && sheets && sheets.find(id);
    if (!hit) return;
    const pane = $('pane-ter'), at = pane.querySelector('.actions');
    const sp = api.S().spaces.find((s) => s.id === id), a = sp && +sp.area_m2 > 0 ? +sp.area_m2 : null;
    const same = a !== null && Math.abs(a - hit.row.m2) < 0.05;
    const box = document.createElement('section');
    box.className = 'sheetref'; box.style.setProperty('--sheet', hit.sheet.color);
    box.innerHTML = `<div class="sheetref__k"><span>Programlap · ${hit.sheet.title}</span><b>${sheets.fmt(hit.row.m2)} m²</b></div>
      <p class="sheetref__nm"></p><p class="sheetref__tx"></p>
      ${same ? '' : `<p class="sheetref__warn">A blob most ${a === null ? 'terület nélküli' : sheets.fmt(a) + ' m²'}, a lap szerint ${sheets.fmt(hit.row.m2)} m².</p>`}
      <button type="button" class="btn">Ugrás a programlaphoz ↓</button>`;
    box.querySelector('.sheetref__nm').textContent = hit.row.name;
    box.querySelector('.sheetref__tx').textContent = sheets.plain(hit.row.text) + (hit.row.links ? ' Tér kapcsolatok: ' + hit.row.links.map((l) => l[1]).join(', ') + '.' : '');
    box.querySelector('button').onclick = () => sheets.reveal(id);
    if (at) at.after(box); else pane.prepend(box);
  });

  $('legendBox').open = false;
  frameCore(false);
})();
